package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_containsNone_TriageGen2Test {

    @Test
    public void testContainsNone_NullInputs() {
        // If cs is null, returns true
        assertTrue(StringUtils.containsNone(null, new char[]{'a'}));
        // If searchChars is null, returns true
        assertTrue(StringUtils.containsNone("abc", null));
        // If both are null, returns true
        assertTrue(StringUtils.containsNone(null, null));
    }

    @Test
    public void testContainsNone_EmptyCharSequence() {
        // Empty string contains none of the characters
        assertTrue(StringUtils.containsNone("", new char[]{'a', 'b'}));
    }

    @Test
    public void testContainsNone_EmptySearchChars() {
        // Empty search array means no character can be "found" to invalidate the "none" condition
        assertTrue(StringUtils.containsNone("abc", new char[]{}));
    }

    @Test
    public void testContainsNone_TrueCases() {
        // None of the characters in cs are in searchChars
        assertTrue(StringUtils.containsNone("abc", new char[]{'d', 'e', 'f'}));
        assertTrue(StringUtils.containsNone("123", new char[]{'a', 'b'}));
        // Test with characters that are smaller than searchChars in Unicode value
        assertTrue(StringUtils.containsNone("!", new char[]{'a'}));
    }

    @Test
    public void testContainsNone_FalseCases_BMP() {
        // 'a' is in searchChars
        assertFalse(StringUtils.containsNone("abc", new char[]{'a'}));
        // 'b' is in searchChars
        assertFalse(StringUtils.containsNone("abc", new char[]{'b'}));
        // Multiple matches
        assertFalse(StringUtils.containsNone("abc", new char[]{'a', 'c'}));
    }

    @Test
    public void testContainsNone_HighSurrogate_Match() {
        // Emoji: 𝄞 (U+1D11E) -> High Surrogate: \uD834, Low Surrogate: \uDD1E
        // We create a char array containing the surrogate pair
        char[] surrogatePair = {'\uD834', '\uDD1E'};

        // Case: cs contains the surrogate pair, and searchChars contains it
        String cs = "\uD834\uDD1E";
        assertFalse(StringUtils.containsNone(cs, surrogatePair));
    }

    @Test
    public void testContainsNone_HighSurrogate_PartialMatch_MissingLowSurrogate() {
        // If the character in cs is a high surrogate but the searchChars only contains the high surrogate
        // and it's the last element in searchChars, the code returns false (meaning it "contains none" is false? 
        // No, the logic says: if (j == searchLast) return false; which means it FOUND a match/invalid char)

        // Note: The implementation logic for surrogates is slightly specialized.
        // If ch is high surrogate and j is searchLast, it returns false (meaning it is NOT "containsNone")
        char[] searchOnlyHigh = {'\uD834'};
        String cs = "\uD834\uDD1E";

        // The code: if (searchChars[j] >= ch) -> '\uD834' >= '\uD834' is true.
        // if (Character.isHighSurrogate(ch)) is true.
        // if (j == searchLast) return false.
        assertFalse(StringUtils.containsNone(cs, searchOnlyHigh));
    }

    @Test
    public void testContainsNone_HighSurrogate_IncompleteMatch() {
        // Test the logic: if (i < csLast && searchChars[j + 1] == cs.charAt(i + 1))
        // This handles the case where the searchChars array contains the full surrogate pair.

        char[] searchWithPair = {'\uD834', '\uDD1E'};
        String cs = "\uD834\uDD1E";

        // j=0, ch=\uD834. searchChars[0] >= ch is true. 
        // isHighSurrogate is true. j (0) != searchLast (1).
        // i (0) < csLast (1) AND searchChars[1] == cs.charAt(1) (\uDD1E == \uDD1E)
        // returns false.
        assertFalse(StringUtils.containsNone(cs, searchWithPair));
    }

    @Test
    public void testContainsNone_HighSurrogate_NoMatch() {
        // High surrogate in cs, but searchChars contains something else
        char[] searchChars = {'\uD835'}; // Different surrogate
        String cs = "\uD834\uDD1E";

        // \uD835 >= \uD834 is true.
        // isHighSurrogate is true.
        // j (0) != searchLast (0) is false.
        // Actually, if searchChars has only 1 element, j == searchLast is true.
        // Let's test a searchChars that doesn't trigger the 'false' return.

        char[] searchCharsNotMatch = {'\u0041'}; // 'A'
        // 'A' >= '\uD834' is false.
        assertTrue(StringUtils.containsNone(cs, searchCharsNotMatch));
    }

    @Test
    public void testContainsNone_UnicodeOrdering() {
        // Testing the 'searchChars[j] >= ch' logic
        // if ch = 'b' (98), searchChars = {'a'} (97). 97 >= 98 is false.
        assertTrue(StringUtils.containsNone("b", new char[]{'a'}));

        // if ch = 'a' (97), searchChars = {'b'} (98). 98 >= 97 is true.
        // Returns false (meaning it contains one of the search chars? 
        // Wait, the logic is: if searchChars[j] >= ch, return false.
        // This means if any char in searchChars is >= ch, it returns false.
        // This is a very specific implementation of "containsNone" where the searchChars 
        // acts as a boundary or a set of forbidden values based on magnitude.
        assertFalse(StringUtils.containsNone("a", new char[]{'b'}));
    }
}
